'use client';

/* SwitchToggle — 开关按钮（源自 PixCreate 面板控件体系的独立化组件）
 * 幽灵轨道样式：标签嵌左、开关嵌右；整行可点，button 原生键盘可达（Space/Enter）
 * 效率控件原则：中性灰白，开态不携带品牌色 */
import './SwitchToggle.css';

export interface SwitchToggleProps {
  label?: string;
  checked?: boolean;
  onChange?: (checked: boolean) => void;
  isDisabled?: boolean;
}

export default function SwitchToggle({
  label = '',
  checked = false,
  onChange,
  isDisabled = false
}: SwitchToggleProps) {
  const toggle = () => {
    if (isDisabled) return;
    onChange?.(!checked);
  };

  return (
    <button
      type="button"
      className="ts-row"
      role="switch"
      aria-checked={checked}
      aria-label={label || undefined}
      disabled={isDisabled}
      data-checked={checked ? 'true' : 'false'}
      onClick={toggle}
    >
      <span className="ts-label">{label}</span>
      <span className="ts-switch">
        <span className="ts-knob" />
      </span>
    </button>
  );
}

/* SwitchToggle — 效率控件：中性灰白，无品牌色 */
.ts-row {
  display: flex;
  align-items: center;
  width: 100%;
  height: var(--control-md);
  padding: 0 var(--space-l);
  border: none; /* 显式清除 button UA 默认边框 */
  border-radius: var(--radius-s);
  background: var(--color-bg-elevated);
  cursor: pointer;
  text-align: left;
  font: inherit;
  outline: none;
  user-select: none;
  transition: transform var(--transition-fast), background-color var(--transition-fast);
}

.ts-row:hover:not([disabled]) {
  background: color-mix(in srgb, #ffffff 5%, var(--color-bg-elevated)); /* hover 白色半透明 */
}

.ts-row[data-checked='true'] {
  background: color-mix(in srgb, #ffffff 5%, var(--color-bg-elevated)); /* 选中态叠亮底 */
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.ts-row:active:not([disabled]) {
  transform: scale(0.985);
}

.ts-row:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--color-text-secondary) 55%, transparent);
  outline-offset: 2px;
}

.ts-row[disabled] {
  opacity: 0.35;
  cursor: not-allowed;
}

.ts-label {
  white-space: nowrap;
  color: var(--color-text-muted);
  font-size: var(--text-sm);
  font-weight: 500;
  letter-spacing: 0.01em;
  pointer-events: none;
}

/* 开关体 — 遵循 reactbits 配色规律：轨道与旋钮永远明暗反转，零饱和中性灰 */
.ts-switch {
  position: relative;
  margin-left: auto;
  width: 36px;
  height: 20px;
  border-radius: 999px;
  background: var(--color-bg-active);
  border: 1px solid rgba(255, 255, 255, 0.1);
  flex-shrink: 0;
  pointer-events: none;
  transition: background-color var(--transition-fast), border-color var(--transition-fast);
}

/* 开态：亮轨道无边（亮色即边界） */
.ts-row[data-checked='true'] .ts-switch {
  background: var(--color-text-primary);
  border-color: transparent;
}

/* 关态：旋钮中灰“浮”在暗轨道上 */
.ts-knob {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 14px;
  height: 14px;
  border-radius: 999px;
  background: var(--color-text-muted);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.24);
  transition: transform var(--transition-fast), background-color var(--transition-fast);
}

/* 开态：旋钮变暗色“孔洞”，与亮轨道反转（浅色主题自动反向：黑轨道+亮旋钮） */
.ts-row[data-checked='true'] .ts-knob {
  transform: translateX(16px);
  background: var(--color-bg-elevated);
}

@media (prefers-reduced-motion: reduce) {
  .ts-row,
  .ts-switch,
  .ts-knob {
    transition-duration: 0.01ms;
  }
}
